// Chapter 12: a 3x3 kernel sliding over a 28x28 chest X-ray (PneumoniaMNIST, CC BY 4.0).
// Pixel data comes from ch12-conv-data.js (window.CH12_XRAYS), generated by scripts/figs_ch12.py.
function initCh12Conv() {
  const root = document.getElementById("ch12-demo");
  if (!root || !window.CH12_XRAYS) return;

  const N = 28;
  const PRESETS = {
    vertical: { name: "垂直邊緣", k: [-1, 0, 1, -2, 0, 2, -1, 0, 1] },
    horizontal: { name: "水平邊緣", k: [-1, -2, -1, 0, 0, 0, 1, 2, 1] },
    blur: { name: "模糊（平均）", k: [1 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 9] },
    sharpen: { name: "銳化", k: [0, -1, 0, -1, 5, -1, 0, -1, 0] },
    identity: { name: "原樣（只有中心 1）", k: [0, 0, 0, 0, 1, 0, 0, 0, 0] },
  };

  // ---------- build DOM
  root.innerHTML = `
    <div class="ch12-row" style="display:flex;flex-wrap:wrap;gap:1rem;align-items:flex-start;justify-content:center;">
      <figure style="margin:0;text-align:center;">
        <canvas id="ch12-in" width="240" height="240" style="width:100%;max-width:240px;image-rendering:pixelated;border-radius:4px;"></canvas>
        <figcaption id="ch12-in-cap" style="font-size:.7rem;"></figcaption>
      </figure>
      <div style="text-align:center;">
        <div style="font-size:.75rem;margin-bottom:.3rem;">濾鏡權重（可直接改）</div>
        <div id="ch12-kernel" style="display:grid;grid-template-columns:repeat(3,3.6rem);gap:4px;justify-content:center;"></div>
        <div id="ch12-calc" style="font-size:.7rem;margin-top:.5rem;max-width:15rem;line-height:1.5;"></div>
      </div>
      <figure style="margin:0;text-align:center;">
        <canvas id="ch12-out" width="240" height="240" style="width:100%;max-width:240px;image-rendering:pixelated;border-radius:4px;"></canvas>
        <figcaption id="ch12-out-cap" style="font-size:.7rem;"></figcaption>
      </figure>
    </div>`;

  const sel = (id) => document.getElementById(id);
  const imgSel = sel("ch12-img");
  const kSel = sel("ch12-preset");
  const strideSel = sel("ch12-stride");
  const padSel = sel("ch12-pad");
  const btnStep = sel("ch12-step");
  const btnPlay = sel("ch12-play");
  const btnAll = sel("ch12-all");
  const info = sel("ch12-info");
  const cIn = sel("ch12-in");
  const cOut = sel("ch12-out");
  const ctxIn = cIn.getContext("2d");
  const ctxOut = cOut.getContext("2d");

  window.CH12_XRAYS.images.forEach((im, i) => imgSel.add(new Option(im.label, String(i))));
  Object.entries(PRESETS).forEach(([key, p]) => kSel.add(new Option(p.name, key)));
  kSel.add(new Option("自訂", "custom"));

  const kInputs = [];
  const kBox = sel("ch12-kernel");
  for (let i = 0; i < 9; i++) {
    const inp = document.createElement("input");
    inp.type = "number";
    inp.step = "0.1";
    inp.setAttribute("aria-label", `濾鏡權重 第 ${Math.floor(i / 3) + 1} 列第 ${(i % 3) + 1} 行`);
    inp.style.cssText = "width:100%;text-align:center;font:inherit;font-size:.8rem;padding:.2rem;" +
      "border:1px solid var(--md-default-fg-color--lighter);border-radius:4px;" +
      "background:var(--md-default-bg-color);color:var(--md-default-fg-color);";
    inp.addEventListener("input", () => { kSel.value = "custom"; recompute(); });
    kBox.appendChild(inp);
    kInputs.push(inp);
  }

  // ---------- state
  let img = [];          // padded image, values 0..1
  let size = N;          // padded side length
  let out = [];          // full output (computed up front, revealed step by step)
  let outN = 0;
  let pos = -1;          // index of the last revealed output cell
  let timer = null;

  const fmt = (v) => (Math.abs(v - Math.round(v)) < 1e-9 ? String(Math.round(v)) : v.toFixed(2));
  const kernel = () => kInputs.map((inp) => parseFloat(inp.value) || 0);

  function setKernel(values) {
    values.forEach((v, i) => { kInputs[i].value = fmt(v); });
  }

  function loadImage() {
    const p = parseInt(padSel.value, 10);
    const px = window.CH12_XRAYS.images[parseInt(imgSel.value, 10)].pixels;
    size = N + 2 * p;
    img = [];
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        const rr = r - p;
        const cc = c - p;
        img.push(rr >= 0 && rr < N && cc >= 0 && cc < N ? px[rr * N + cc] / 255 : 0);
      }
    }
  }

  function recompute() {
    stop();
    loadImage();
    const s = parseInt(strideSel.value, 10);
    const p = parseInt(padSel.value, 10);
    const k = kernel();
    outN = Math.floor((size - 3) / s) + 1;
    out = [];
    for (let i = 0; i < outN; i++) {
      for (let j = 0; j < outN; j++) {
        let sum = 0;
        for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) sum += img[(i * s + a) * size + (j * s + b)] * k[a * 3 + b];
        out.push(sum);
      }
    }
    pos = -1;
    info.textContent = `輸出邊長 = (n + 2p − k) / s + 1 = (28 + 2×${p} − 3) / ${s} + 1 = ${outN}` +
      `（無條件捨去）。按「下一步」看濾鏡一格一格滑動，或按「全部算完」。`;
    sel("ch12-out-cap").textContent = `特徵圖 ${outN}×${outN}`;
    sel("ch12-in-cap").textContent = p ? `輸入 28×28（外圍補 ${p} 圈 0 → ${size}×${size}）` : "輸入 28×28";
    draw();
  }

  // ---------- drawing
  function draw() {
    const s = parseInt(strideSel.value, 10);
    const k = kernel();
    const W = cIn.width;
    const cell = W / size;
    ctxIn.clearRect(0, 0, W, W);
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        const v = Math.round(img[r * size + c] * 255);
        ctxIn.fillStyle = `rgb(${v},${v},${v})`;
        ctxIn.fillRect(c * cell, r * cell, Math.ceil(cell), Math.ceil(cell));
      }
    }
    if (size > N) { // mark the original image border when padded
      ctxIn.strokeStyle = "#607D8B";
      ctxIn.lineWidth = 1;
      const p = (size - N) / 2;
      ctxIn.strokeRect(p * cell, p * cell, N * cell, N * cell);
    }

    const Wo = cOut.width;
    const oc = Wo / outN;
    ctxOut.clearRect(0, 0, Wo, Wo);
    ctxOut.fillStyle = "rgba(158,158,158,0.18)";
    ctxOut.fillRect(0, 0, Wo, Wo);
    const signed = k.some((v) => v < 0);
    const maxAbs = Math.max(1e-9, ...out.map(Math.abs));
    const maxV = Math.max(1e-9, ...out);
    for (let idx = 0; idx <= pos; idx++) {
      const v = out[idx];
      let color;
      if (signed) { // diverging: blue (negative) - white - red (positive)
        const t = Math.max(-1, Math.min(1, v / maxAbs));
        const end = t >= 0 ? [178, 24, 43] : [33, 102, 172];
        const u = Math.abs(t);
        color = `rgb(${end.map((e) => Math.round(255 + (e - 255) * u)).join(",")})`;
      } else {
        const g = Math.round(255 * Math.max(0, Math.min(1, v / maxV)));
        color = `rgb(${g},${g},${g})`;
      }
      ctxOut.fillStyle = color;
      ctxOut.fillRect((idx % outN) * oc, Math.floor(idx / outN) * oc, Math.ceil(oc), Math.ceil(oc));
    }

    const calc = sel("ch12-calc");
    if (pos >= 0 && pos < out.length) {
      const i = Math.floor(pos / outN);
      const j = pos % outN;
      ctxIn.strokeStyle = "#F4511E";
      ctxIn.lineWidth = 3;
      ctxIn.strokeRect(j * s * cell, i * s * cell, 3 * cell, 3 * cell);
      ctxOut.strokeStyle = "#F4511E";
      ctxOut.lineWidth = 3;
      ctxOut.strokeRect(j * oc, i * oc, oc, oc);
      const patch = [];
      for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) patch.push(img[(i * s + a) * size + (j * s + b)]);
      calc.textContent = `位置（第 ${i + 1} 列, 第 ${j + 1} 行）：9 個像素 × 9 個權重再加總 = ` +
        patch.map((v, n) => `${v.toFixed(2)}×${k[n] < 0 ? `(${fmt(k[n])})` : fmt(k[n])}`).join(" + ") + ` = ${out[pos].toFixed(2)}`;
    } else {
      calc.textContent = signed ? "特徵圖顏色：紅 = 正、藍 = 負、白 ≈ 0" : "特徵圖顏色：越亮代表輸出越大";
    }
  }

  // ---------- controls
  function step() {
    if (pos < out.length - 1) { pos += 1; draw(); } else stop();
  }
  function stop() {
    if (timer) { clearInterval(timer); timer = null; }
    btnPlay.textContent = "自動播放";
  }
  btnStep.addEventListener("click", () => { stop(); step(); });
  btnPlay.addEventListener("click", () => {
    if (timer) { stop(); return; }
    if (pos >= out.length - 1) pos = -1;
    btnPlay.textContent = "暫停";
    timer = setInterval(() => { for (let n = 0; n < 3; n++) step(); }, 40);
  });
  btnAll.addEventListener("click", () => { stop(); pos = out.length - 1; draw(); });
  kSel.addEventListener("change", () => {
    if (kSel.value !== "custom") setKernel(PRESETS[kSel.value].k);
    recompute();
  });
  [imgSel, strideSel, padSel].forEach((el) => el.addEventListener("change", recompute));

  kSel.value = "vertical";
  setKernel(PRESETS.vertical.k);
  recompute();
}

if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", initCh12Conv);
else initCh12Conv();
